using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;
public static partial class FinanceEndpoints {
 static void MapPortal(RouteGroupBuilder t){
 t.MapGet("/my/summary",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);var mine=db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)).Select(m=>m.Id);var q=db.Set<FinanceInvoice>().Where(i=>i.TenantId==tenant&&i.Status=="Issued"&&i.Kind=="Invoice"&&(i.MembershipId!=null&&mine.Contains(i.MembershipId.Value)||i.RegistrationId!=null&&db.Set<EventRegistration>().Any(r=>r.Id==i.RegistrationId&&r.UserId==a.UserId)));return Results.Ok(new{balances=await q.GroupBy(i=>new{i.EntityId,i.Currency}).Select(g=>new{g.Key.EntityId,g.Key.Currency,charges=g.Sum(i=>i.Total),credits=g.Sum(i=>i.Credited),paid=g.Sum(i=>i.Paid),outstanding=g.Sum(i=>i.Total-i.Paid-i.Credited),overdue=g.Where(i=>i.DueOn<FinanceService.Today).Sum(i=>i.Total-i.Paid-i.Credited)}).ToListAsync(),nextDue=await q.Where(i=>i.Total>i.Paid+i.Credited).OrderBy(i=>i.DueOn).Select(i=>(DateOnly?)i.DueOn).FirstOrDefaultAsync(),memberships=await db.Memberships.Where(m=>mine.Contains(m.Id)).Select(m=>new{m.Id,m.Number,m.ChapterId,m.Status,m.EndsAt}).ToListAsync()});});
 t.MapGet("/my/invoices",async(Guid tenant,int? page,AppDb db,Access a)=>{await a.Member(tenant);var mine=db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)).Select(m=>m.Id);var q=db.Set<FinanceInvoice>().Where(i=>i.TenantId==tenant&&i.Status=="Issued"&&(i.MembershipId!=null&&mine.Contains(i.MembershipId.Value)||i.RegistrationId!=null&&db.Set<EventRegistration>().Any(r=>r.Id==i.RegistrationId&&r.UserId==a.UserId)));return Results.Ok(new{total=await q.CountAsync(),items=(await q.OrderByDescending(i=>i.Date).Skip(Page(page)*50).Take(50).ToListAsync()).Select(InvoiceDto)});});
 t.MapGet("/my/payments",async(Guid tenant,int? page,AppDb db,Access a)=>{await a.Member(tenant);var mine=db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)).Select(m=>m.Id);var q=db.Set<FinancePayment>().Where(p=>p.TenantId==tenant&&p.Status=="Confirmed"&&(p.MembershipId!=null&&mine.Contains(p.MembershipId.Value)||db.Set<PaymentIntent>().Any(i=>i.PaymentId==p.Id&&i.UserId==a.UserId)));return Results.Ok(new{total=await q.CountAsync(),items=await q.OrderByDescending(p=>p.Date).Skip(Page(page)*50).Take(50).Select(p=>new{p.Id,p.Reference,p.Amount,p.Currency,p.Method,p.Date,p.Refunded,p.Status,receipt=db.Set<FinanceReceipt>().Where(r=>r.PaymentId==p.Id).Select(r=>new{r.Id,r.Number}).FirstOrDefault(),allocations=db.Set<PaymentAllocation>().Where(x=>x.PaymentId==p.Id).Select(x=>new{x.InvoiceId,x.Amount}).ToArray()}).ToListAsync()});});
 t.MapGet("/my/receipts",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);var mine=db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)).Select(m=>m.Id);return await (from r in db.Set<FinanceReceipt>() join p in db.Set<FinancePayment>() on r.PaymentId equals p.Id where r.TenantId==tenant&&(p.MembershipId!=null&&mine.Contains(p.MembershipId.Value)||db.Set<PaymentIntent>().Any(i=>i.PaymentId==p.Id&&i.UserId==a.UserId)) orderby r.At descending select new{r.Id,r.Number,r.PaymentId,r.Amount,r.Currency,r.At}).Take(100).ToListAsync();});
 t.MapGet("/my/statements/{member:guid}/export",async(Guid tenant,Guid member,string format,Guid? entity,DateOnly? from,DateOnly? to,AppDb db,Access a,FinanceService s,FinanceDocuments pdf)=>{await a.Member(tenant);if(!await db.Memberships.AnyAsync(m=>m.Id==member&&m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)))throw new AccessDeniedException();if(format is not("pdf" or "csv" or "xlsx"))throw new DomainException("Use PDF, CSV or Excel");var statement=JsonSerializer.SerializeToElement(await Statement(tenant,entity,member,null,from,to,db,s,true),FinanceExport.Web);if(statement.GetProperty("truncated").GetBoolean())throw new DomainException("Narrow this date range to at most 1,000 statement entries");var rows=statement.GetProperty("balances").EnumerateArray().Select(FinanceExport.Summary).Concat(statement.GetProperty("items").EnumerateArray()).ToArray();var bytes=FinanceExport.Encode("Member statement",format,rows,pdf);return Results.File(bytes,format=="pdf"?"application/pdf":format=="xlsx"?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"text/csv","statement."+format);});
 }
 static void MapFinanceEvents(RouteGroupBuilder t){
 t.MapGet("/event-policies",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<EventFinancePolicy>(tenant,entity:entity).Take(200).ToListAsync());
 t.MapPost("/event-policies",async(Guid tenant,EventFinancePolicy r,AppDb db,Access a,FinanceService s)=>{var e=await s.Require(tenant,r.EntityId,r.UnitId,"finance.invoice");await a.Require(tenant,"events.manage",r.UnitId);if(!await db.Set<CommunityEvent>().AnyAsync(x=>x.TenantId==tenant&&x.Id==r.EventId&&x.UnitId==r.UnitId)||await db.Set<EventRegistration>().AnyAsync(x=>x.TenantId==tenant&&x.EventId==r.EventId))throw new DomainException("Configure event pricing before registrations begin");FinanceService.Money(r.MemberPrice,e.Currency,false);FinanceService.Money(r.GuestPrice,e.Currency,false);var policy=new EventFinancePolicy{TenantId=tenant,EntityId=e.Id,UnitId=r.UnitId,EventId=r.EventId,MemberPrice=r.MemberPrice,GuestPrice=r.GuestPrice,Currency=e.Currency,AllowManualSettlement=r.AllowManualSettlement,AuthorId=a.UserId,Active=false};db.Add(policy);a.Audit(tenant,"finance.event-pricing.requested",policy.Id);await db.SaveChangesAsync();return Results.Ok(policy);});
 t.MapPost("/event-policies/{id:guid}/decision",async(Guid tenant,Guid id,FinanceDecision r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var p=await db.Set<EventFinancePolicy>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id&&p.ApprovedBy==null)??throw new AccessDeniedException();var e=await s.Require(tenant,p.EntityId,p.UnitId,"finance.approve");await s.Review(tenant,id,p.AuthorId,p.UnitId!.Value,"FinanceEventPricing",r,Math.Max(p.MemberPrice,p.GuestPrice),e);p.Active=r.Decision=="Approve";p.ApprovedBy=r.Decision=="Approve"?a.UserId:null;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(p);});
 t.MapGet("/events/{id:guid}/pricing",async(Guid tenant,Guid id,AppDb db,CommunityService community)=>{await community.Event(tenant,id);return Results.Ok(await db.Set<EventFinancePolicy>().Where(p=>p.TenantId==tenant&&p.EventId==id&&p.Active&&p.ApprovedBy!=null).Select(p=>new{p.MemberPrice,p.GuestPrice,p.Currency,p.AllowManualSettlement,p.EntityId}).SingleOrDefaultAsync());});
 t.MapPost("/events/{id:guid}/registration-invoice",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s,CommunityService community)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);await EventEndpoints.Lock(db,tenant,id);var e=await community.Event(tenant,id);var registration=await db.Set<EventRegistration>().SingleOrDefaultAsync(r=>r.TenantId==tenant&&r.EventId==id&&r.UserId==a.UserId&&r.Status=="Awaiting Payment")??throw new DomainException("Register and receive any required event approval before payment");var prior=await db.Set<FinanceInvoice>().SingleOrDefaultAsync(i=>i.TenantId==tenant&&i.RegistrationId==registration.Id&&i.Kind=="Invoice");if(prior!=null)return Results.Ok(InvoiceDto(prior));var policy=await db.Set<EventFinancePolicy>().SingleAsync(p=>p.TenantId==tenant&&p.EventId==id&&p.Active&&p.ApprovedBy!=null);if(!await MailWorker.Authority(db,tenant,policy.ApprovedBy!.Value,policy.UnitId,"finance.approve"))throw new DomainException("Pricing approval authority is no longer valid");var fee=(registration.MembershipId==null?policy.GuestPrice:policy.MemberPrice)+registration.Companions*policy.GuestPrice;var invoice=await s.CreateInvoice(tenant,new(policy.EntityId,policy.UnitId!.Value,registration.Name,FinanceService.Today,DateOnly.FromDateTime(e.RegistrationCloses.UtcDateTime),[new(e.Title+" registration",1,fee,0,0,"4200")],registration.MembershipId,Purpose:"Event registration",EventId:id),true);invoice.RegistrationId=registration.Id;await db.SaveChangesAsync();var entity=await db.Set<FinancialEntity>().SingleAsync(x=>x.Id==policy.EntityId);await s.Issue(invoice,entity,policy.ApprovedBy);if(fee==0)await s.ConfirmEvent(invoice);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(InvoiceDto(invoice));});
 }
}
